using Prixo.Domain.Common;
using Prixo.Domain.Enums;

namespace Prixo.Domain.Entities.Patients;

/// <summary>
/// A consent request initiated by this facility (Milestone M3 - HIU) to request health records
/// for a patient from other ABDM participants.
/// </summary>
public class AbdmConsentRequest : BaseEntity
{
    public long PatientId { get; set; }
    public Patient? Patient { get; set; }

    /// <summary>Unique request identifier generated by/for ABDM.</summary>
    public required string ConsentRequestId { get; set; }

    /// <summary>ABDM Consent Artifact ID issued once patient approves the request in their PHR app.</summary>
    public string? ConsentArtifactId { get; set; }

    /// <summary>Patient's 14-digit ABHA Number.</summary>
    public required string AbhaNumber { get; set; }

    /// <summary>Patient's ABHA Address (e.g. name@abdm).</summary>
    public string? AbhaAddress { get; set; }

    /// <summary>Purpose code (e.g. CAET = Care Management, BTG = Break The Glass, PUBHLTH = Public Health).</summary>
    public required string Purpose { get; set; }

    /// <summary>Comma-separated list of HI types requested (e.g. "OPConsultation,Prescription,DiagnosticReport,DischargeSummary").</summary>
    public required string HiTypes { get; set; }

    /// <summary>Start date for health records requested.</summary>
    public DateTimeOffset DateFrom { get; set; }

    /// <summary>End date for health records requested.</summary>
    public DateTimeOffset DateTo { get; set; }

    /// <summary>Consent validity expiry date/time.</summary>
    public DateTimeOffset ExpiryAt { get; set; }

    /// <summary>Current state of the consent request.</summary>
    public AbdmConsentStatus Status { get; set; } = AbdmConsentStatus.Requested;

    /// <summary>When the status was last updated (e.g. patient approved/denied).</summary>
    public DateTimeOffset? StatusUpdatedAt { get; set; }

    public long? RequesterDoctorId { get; set; }
    public string? RequesterDoctorName { get; set; }
}
